////////////////////////////////////////////////////////////////////////////////
// Module: system_top
//
// Example system with the files of hdl/v2005 (Verilog-2005, no localparam):
//
//   PC --UART--> hexbus_axil_top --M_AXI--> axil_xbar (1 x 2) --SLAVE0--> axilgpio_a32  0x0301_0000
//                                                             --SLAVE1--> axiluart_phy  0x0302_0000
//
// axil_xbar.v is the wrapper generated by AXIL Studio's Interconnect Configurator for this
// address map, passed through no_localparam.py. Any address outside the two windows gets DECERR.
// Files: example/*.v, hexbus/*.v, wbuart32/*.v, uart_phy/*.v, interconnect/*.v, gpio/*.v, common/*.v
////////////////////////////////////////////////////////////////////////////////

`default_nettype none

module system_top #(
    parameter integer CLK_FREQ_HZ = 50_000_000,   // clk frequency
    parameter integer BAUD_RATE   = 115_200,      // debug UART (hexbus)
    parameter [30:0]  UART_SETUP  = 31'd434       // axiluart_phy reset SETUP ([23:0] = clk / baud)
) (
    input  wire       clk,
    input  wire       rst_n,
    // debug UART to the PC (hexbus)
    input  wire       i_dbg_rx,
    output wire       o_dbg_tx,
    // GPIO
    output wire [7:0] o_gpio,
    input  wire [3:0] i_gpio,
    // UART PHY line
    output wire       o_txd,
    input  wire       i_rxd,
    output wire       o_de,
    output wire       o_re_n
);

    // ---- hexbus -> interconnect
    wire        m_awvalid, m_awready, m_wvalid, m_wready, m_bvalid, m_bready;
    wire        m_arvalid, m_arready, m_rvalid, m_rready;
    wire [31:0] m_awaddr, m_wdata, m_araddr, m_rdata;
    wire [2:0]  m_awprot, m_arprot;
    wire [3:0]  m_wstrb;
    wire [1:0]  m_bresp, m_rresp;

    hexbus_axil_top #(
        .CLK_FREQ_HZ(CLK_FREQ_HZ), .BAUD_RATE(BAUD_RATE), .C_AXI_ADDR_WIDTH(32)
    ) u_hexbus (
        .S_AXI_ACLK(clk), .S_AXI_ARESETN(rst_n),
        .i_uart_rx(i_dbg_rx), .o_uart_tx(o_dbg_tx), .i_interrupt(1'b0),
        .M_AXI_AWVALID(m_awvalid), .M_AXI_AWREADY(m_awready), .M_AXI_AWADDR(m_awaddr),
        .M_AXI_AWPROT(m_awprot), .M_AXI_WVALID(m_wvalid), .M_AXI_WREADY(m_wready),
        .M_AXI_WDATA(m_wdata), .M_AXI_WSTRB(m_wstrb), .M_AXI_BVALID(m_bvalid),
        .M_AXI_BREADY(m_bready), .M_AXI_BRESP(m_bresp), .M_AXI_ARVALID(m_arvalid),
        .M_AXI_ARREADY(m_arready), .M_AXI_ARADDR(m_araddr), .M_AXI_ARPROT(m_arprot),
        .M_AXI_RVALID(m_rvalid), .M_AXI_RREADY(m_rready), .M_AXI_RDATA(m_rdata),
        .M_AXI_RRESP(m_rresp),
        .M_AXI_AWLEN(), .M_AXI_AWSIZE(), .M_AXI_AWBURST(), .M_AXI_WLAST(),
        .M_AXI_ARLEN(), .M_AXI_ARSIZE(), .M_AXI_ARBURST()
    );

    // ---- interconnect -> slaves
    wire        g_awvalid, g_awready, g_wvalid, g_wready, g_bvalid, g_bready;
    wire        g_arvalid, g_arready, g_rvalid, g_rready;
    wire [31:0] g_awaddr, g_wdata, g_araddr, g_rdata;
    wire [2:0]  g_awprot, g_arprot;
    wire [3:0]  g_wstrb;
    wire [1:0]  g_bresp, g_rresp;

    wire        u_awvalid, u_awready, u_wvalid, u_wready, u_bvalid, u_bready;
    wire        u_arvalid, u_arready, u_rvalid, u_rready;
    wire [31:0] u_awaddr, u_wdata, u_araddr, u_rdata;
    wire [2:0]  u_awprot, u_arprot;
    wire [3:0]  u_wstrb;
    wire [1:0]  u_bresp, u_rresp;

    axil_xbar u_xbar (
        .ACLK(clk), .ARESETN(rst_n),
        .MASTER0_AXI_AWADDR(m_awaddr), .MASTER0_AXI_AWPROT(m_awprot),
        .MASTER0_AXI_AWVALID(m_awvalid), .MASTER0_AXI_AWREADY(m_awready),
        .MASTER0_AXI_WDATA(m_wdata), .MASTER0_AXI_WSTRB(m_wstrb),
        .MASTER0_AXI_WVALID(m_wvalid), .MASTER0_AXI_WREADY(m_wready),
        .MASTER0_AXI_BRESP(m_bresp), .MASTER0_AXI_BVALID(m_bvalid), .MASTER0_AXI_BREADY(m_bready),
        .MASTER0_AXI_ARADDR(m_araddr), .MASTER0_AXI_ARPROT(m_arprot),
        .MASTER0_AXI_ARVALID(m_arvalid), .MASTER0_AXI_ARREADY(m_arready),
        .MASTER0_AXI_RDATA(m_rdata), .MASTER0_AXI_RRESP(m_rresp),
        .MASTER0_AXI_RVALID(m_rvalid), .MASTER0_AXI_RREADY(m_rready),

        .SLAVE0_AXI_AWADDR(g_awaddr), .SLAVE0_AXI_AWPROT(g_awprot),
        .SLAVE0_AXI_AWVALID(g_awvalid), .SLAVE0_AXI_AWREADY(g_awready),
        .SLAVE0_AXI_WDATA(g_wdata), .SLAVE0_AXI_WSTRB(g_wstrb),
        .SLAVE0_AXI_WVALID(g_wvalid), .SLAVE0_AXI_WREADY(g_wready),
        .SLAVE0_AXI_BRESP(g_bresp), .SLAVE0_AXI_BVALID(g_bvalid), .SLAVE0_AXI_BREADY(g_bready),
        .SLAVE0_AXI_ARADDR(g_araddr), .SLAVE0_AXI_ARPROT(g_arprot),
        .SLAVE0_AXI_ARVALID(g_arvalid), .SLAVE0_AXI_ARREADY(g_arready),
        .SLAVE0_AXI_RDATA(g_rdata), .SLAVE0_AXI_RRESP(g_rresp),
        .SLAVE0_AXI_RVALID(g_rvalid), .SLAVE0_AXI_RREADY(g_rready),

        .SLAVE1_AXI_AWADDR(u_awaddr), .SLAVE1_AXI_AWPROT(u_awprot),
        .SLAVE1_AXI_AWVALID(u_awvalid), .SLAVE1_AXI_AWREADY(u_awready),
        .SLAVE1_AXI_WDATA(u_wdata), .SLAVE1_AXI_WSTRB(u_wstrb),
        .SLAVE1_AXI_WVALID(u_wvalid), .SLAVE1_AXI_WREADY(u_wready),
        .SLAVE1_AXI_BRESP(u_bresp), .SLAVE1_AXI_BVALID(u_bvalid), .SLAVE1_AXI_BREADY(u_bready),
        .SLAVE1_AXI_ARADDR(u_araddr), .SLAVE1_AXI_ARPROT(u_arprot),
        .SLAVE1_AXI_ARVALID(u_arvalid), .SLAVE1_AXI_ARREADY(u_arready),
        .SLAVE1_AXI_RDATA(u_rdata), .SLAVE1_AXI_RRESP(u_rresp),
        .SLAVE1_AXI_RVALID(u_rvalid), .SLAVE1_AXI_RREADY(u_rready)
    );

    // ---- SLAVE0: GPIO, 0x0301_0000
    wire gpio_int;
    axilgpio_a32 #(.NOUT(8), .NIN(4)) u_gpio (
        .S_AXI_ACLK(clk), .S_AXI_ARESETN(rst_n),
        .S_AXI_AWVALID(g_awvalid), .S_AXI_AWREADY(g_awready), .S_AXI_AWADDR(g_awaddr),
        .S_AXI_AWPROT(g_awprot), .S_AXI_WVALID(g_wvalid), .S_AXI_WREADY(g_wready),
        .S_AXI_WDATA(g_wdata), .S_AXI_WSTRB(g_wstrb), .S_AXI_BVALID(g_bvalid),
        .S_AXI_BREADY(g_bready), .S_AXI_BRESP(g_bresp), .S_AXI_ARVALID(g_arvalid),
        .S_AXI_ARREADY(g_arready), .S_AXI_ARADDR(g_araddr), .S_AXI_ARPROT(g_arprot),
        .S_AXI_RVALID(g_rvalid), .S_AXI_RREADY(g_rready), .S_AXI_RDATA(g_rdata),
        .S_AXI_RRESP(g_rresp),
        .o_gpio(o_gpio), .i_gpio(i_gpio), .o_int(gpio_int)
    );

    // ---- SLAVE1: UART PHY, 0x0302_0000 (decodes address bits [4:0])
    wire rts_n, rx_int, tx_int, rxf_int, txf_int;
    axiluart_phy #(.INITIAL_SETUP(UART_SETUP)) u_uart (
        .S_AXI_ACLK(clk), .S_AXI_ARESETN(rst_n),
        .S_AXI_AWVALID(u_awvalid), .S_AXI_AWREADY(u_awready), .S_AXI_AWADDR(u_awaddr[4:0]),
        .S_AXI_AWPROT(u_awprot), .S_AXI_WVALID(u_wvalid), .S_AXI_WREADY(u_wready),
        .S_AXI_WDATA(u_wdata), .S_AXI_WSTRB(u_wstrb), .S_AXI_BVALID(u_bvalid),
        .S_AXI_BREADY(u_bready), .S_AXI_BRESP(u_bresp), .S_AXI_ARVALID(u_arvalid),
        .S_AXI_ARREADY(u_arready), .S_AXI_ARADDR(u_araddr[4:0]), .S_AXI_ARPROT(u_arprot),
        .S_AXI_RVALID(u_rvalid), .S_AXI_RREADY(u_rready), .S_AXI_RDATA(u_rdata),
        .S_AXI_RRESP(u_rresp),
        .o_txd(o_txd), .i_rxd(i_rxd), .o_de(o_de), .o_re_n(o_re_n),
        .o_rts_n(rts_n), .i_cts_n(1'b0),
        .o_uart_rx_int(rx_int), .o_uart_tx_int(tx_int),
        .o_uart_rxfifo_int(rxf_int), .o_uart_txfifo_int(txf_int)
    );

    wire unused = &{1'b0, gpio_int, rts_n, rx_int, tx_int, rxf_int, txf_int,
                    u_awaddr[31:5], u_araddr[31:5]};

endmodule

`default_nettype wire
